        "h": 30,
        "text": "매년 강화되는 세법에 맞춰 상속·증여세 절세 플랜\n이 매년 업데이트되고 있는가?",
        "font": "Pretendard",
        "weight": 400,
        "color": "#222",
        "align": "left",
        "inkFit": false,
        "lineHeight": 1.22,
        "size": 13.764642164144627
