        "text": "비즈대학교 음악대학 지휘과 졸업\n독일 비즈 국립음대 석사\n비즈 국제 지휘 콩쿠르 대상\n비즈 필하모닉 객원지휘\n현 비즈 심포니 오케스트라 음악감독",
