        "text": "오늘의 프로그램은 고전주의부터 낭만주의를 대표하는 작품들로 구\n성되었습니다. 모차르트의 경쾌한 서곡을 시작으로, 베토벤의 강렬한\n교향곡, 차이콥스키의 서정적인 발레 음악, 그리고 드보르자크의 웅장\n한 교향곡을 통해 오케스트라 음악의 다양한 매력을 만나보실 수 있\n습니다.",
